pub extern "C" fn tpchq9vgens_new() -> *mut QStore {
    Box::into_raw(Box::new(Store::new(0, Slot::Invalid, 0, Ghost::assume_new())))
}

/// Free a store.
#[no_mangle]
pub unsafe extern "C" fn tpchq9vgens_free(st: *mut QStore) {
    if !st.is_null() {
        drop(Box::from_raw(st));
    }
}

/// The newest version's state, to prepare the next version from; NULL if
/// it is invalid.
#[no_mangle]
pub unsafe extern "C" fn tpchq9vgens_newest_base(st: *const QStore) -> *mut QBase {
    match base(&*st) {
        Some(b) => Box::into_raw(Box::new(b)),
        None => ptr::null_mut(),
    }
}

/// The base's state (valid while the base is).
#[no_mangle]
pub unsafe extern "C" fn tpchq9vgens_base_state(b: *const QBase) -> *const State {
    (*b).state() as *const State
}

/// Free a base.
#[no_mangle]
pub unsafe extern "C" fn tpchq9vgens_base_free(b: *mut QBase) {
    if !b.is_null() {
        drop(Box::from_raw(b));
    }
}

